  "blog.resampling.nearest.title": "1. Nearest Neighbor (The Pixel Artist's Choice)",
  "blog.resampling.nearest.when_to_use": "<strong>When to Use:</strong> Always for upscaling pixel art. Often for downscaling if maintaining sharp edges is paramount.",
